def factorial(n, max_limit=None):
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be an integer greater than or equal to 0")

    if max_limit is not None and n > max_limit:
        raise ValueError(f"Factorial of {n} exceeds the maximum limit of {max_limit}")

    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)
